"""Pure-function KPI aggregator for `harness site`.

Reads activity JSONLs + state file + per-feature VALIDATION-*.md files,
emits structured metrics consumed by the kpi.md.j2 template.

No I/O at the function level — caller passes already-loaded data. Makes
unit testing trivial.
"""

from __future__ import annotations

import json
import re
from collections.abc import Iterable
from dataclasses import dataclass, field
from datetime import UTC, datetime, timedelta
from pathlib import Path
from typing import Any

# ---- data model -----------------------------------------------------------


@dataclass
class ActivityEntry:
    """One line from docs/activity/<YYYY-MM>.jsonl."""

    ts: datetime
    user: str
    session_id: str | None
    kind: str  # "command" (other kinds reserved for future)
    command: str | None
    feature: str | None
    duration_s: int
    outcome: str  # completed | aborted | error
    intervention_count: int
    files_created: int = 0
    files_modified: int = 0
    lines_added: int = 0
    tool_rejections: int = 0
    cmd_ts: str | None = None  # invocation key; one record per (session, cmd_ts)
    # Token usage (records written before the token fields shipped carry zeros)
    input_token: int = 0
    output_token: int = 0
    cache_read: int = 0
    cache_write: int = 0
    total_tokens: int = 0
    # model id -> {input, output, cache_read, cache_write_5m, cache_write_1h}
    models: dict[str, Any] = field(default_factory=dict)


@dataclass
class UserSummary:
    user: str
    sessions: int
    commands: int
    total_seconds: int
    top_command: str

    @property
    def total_label(self) -> str:
        return _humanize_seconds(self.total_seconds)


@dataclass
class FeatureVelocity:
    feature: str
    first_intake_ts: datetime | None
    last_review_pass_ts: datetime | None

    @property
    def cycle_time_label(self) -> str:
        if not self.first_intake_ts or not self.last_review_pass_ts:
            return "open"
        delta = self.last_review_pass_ts - self.first_intake_ts
        return _humanize_timedelta(delta)


@dataclass
class CommandFriction:
    command: str
    runs: int
    mean_interventions: float
    repeat_rate: float  # fraction (0.0-1.0) of features that ran the command 2+ times
    score: float  # composite friction
    tier: str  # "🟢" / "🟡" / "🔴"


@dataclass
class KPIWindow:
    """Computed KPIs for one time window."""

    window_label: str  # "last 7 days"
    window_start: datetime
    window_end: datetime
    active_users: list[str]
    total_commands: int
    total_seconds: int
    mean_cycle_seconds: int | None  # mean across features whose cycle closed in window
    velocity: list[FeatureVelocity]
    validation_rounds_mean: float | None
    stack_smoke_pass_rate: float | None  # 0.0-1.0
    carry_forward_open: int
    error_rate: float  # 0.0-1.0
    friction: list[CommandFriction]
    per_user: list[UserSummary]
    # Code-change activity totals
    files_created_total: int = 0
    files_modified_total: int = 0
    lines_added_total: int = 0
    tool_rejections_total: int = 0

    @property
    def mean_cycle_label(self) -> str:
        if self.mean_cycle_seconds is None:
            return "—"
        return _humanize_seconds(self.mean_cycle_seconds)

    @property
    def total_seconds_label(self) -> str:
        return _humanize_seconds(self.total_seconds)


# ---- public API -----------------------------------------------------------


def parse_activity_jsonl(path: Path) -> list[ActivityEntry]:
    """Parse one docs/activity/<YYYY-MM>.jsonl file into ActivityEntry list."""
    entries: list[ActivityEntry] = []
    text = path.read_text(encoding="utf-8")
    for line in text.splitlines():
        line = line.strip()
        if not line:
            continue
        try:
            obj = json.loads(line)
        except json.JSONDecodeError:
            continue
        try:
            ts = datetime.fromisoformat(obj["ts"].replace("Z", "+00:00"))
        except (KeyError, ValueError):
            continue
        entries.append(
            ActivityEntry(
                ts=ts,
                user=str(obj.get("user", "unknown")).lower(),
                session_id=obj.get("session_id"),
                kind=str(obj.get("kind", "command")),
                command=obj.get("command"),
                feature=obj.get("feature"),
                duration_s=int(obj.get("duration_s") or 0),
                outcome=str(obj.get("outcome", "completed")),
                intervention_count=int(obj.get("intervention_count") or 0),
                files_created=int(obj.get("files_created") or 0),
                files_modified=int(obj.get("files_modified") or 0),
                lines_added=int(obj.get("lines_added") or 0),
                tool_rejections=int(obj.get("tool_rejections") or 0),
                cmd_ts=obj.get("cmd_ts"),
                input_token=int(obj.get("input_token") or 0),
                output_token=int(obj.get("output_token") or 0),
                cache_read=int(obj.get("cache_read") or 0),
                cache_write=int(obj.get("cache_write") or 0),
                total_tokens=int(obj.get("total") or 0),
                models=obj.get("models") if isinstance(obj.get("models"), dict) else {},
            )
        )
    return entries


def parse_all_activity(paths: Iterable[Path]) -> list[ActivityEntry]:
    """Parse every docs/activity/*.jsonl file; return combined list sorted by ts.

    The hook upserts one record per command invocation, so well-formed files
    carry no duplicates. This still dedups defensively by
    (session_id, command, cmd_ts) — keeping the last occurrence — to neutralise
    any legacy append-per-Stop data where the same invocation was written many
    times with cumulative-growth counts. Entries lacking cmd_ts (pre-upsert
    schema) cannot be safely collapsed and are kept as-is.
    """
    combined: list[ActivityEntry] = []
    for p in paths:
        combined.extend(parse_activity_jsonl(p))
    deduped: dict[tuple[str | None, str | None, str], ActivityEntry] = {}
    legacy: list[ActivityEntry] = []
    for e in combined:
        if e.cmd_ts and e.session_id:
            deduped[(e.session_id, e.command, e.cmd_ts)] = e  # last write wins
        else:
            legacy.append(e)
    result = list(deduped.values()) + legacy
    result.sort(key=lambda e: e.ts)
    return result


def compute_kpi_window(
    entries: list[ActivityEntry],
    *,
    window_days: int,
    now: datetime | None = None,
    state_raw: dict | None = None,
    validation_summaries: dict[str, str] | None = None,
) -> KPIWindow:
    """Compute KPI metrics for a single window.

    Args:
        entries: ALL activity entries (filtered by window inside this function)
        window_days: window size in days; window = [now - window_days, now]
        now: anchor; defaults to current UTC. Override for tests.
        state_raw: feature_id -> record dict; builder merges per-feature
            (`docs/features/<id>/state.json`) over index (`docs/state/features.json`)
            so P-tier fields (validation_summary, pending_carry_forward) reach this code.
        validation_summaries: feature_id -> latest VALIDATION-*.md body (for stack-smoke parse)
    """
    if now is None:
        now = datetime.now(UTC)
    window_start = now - timedelta(days=window_days)
    window_end = now
    state_raw = state_raw or {}
    validation_summaries = validation_summaries or {}

    in_window = [e for e in entries if window_start <= e.ts <= window_end]

    # --- active users
    users = sorted({e.user for e in in_window})

    # --- totals
    total_commands = len(in_window)
    total_seconds = sum(e.duration_s for e in in_window)

    # --- velocity per feature
    by_feature: dict[str, list[ActivityEntry]] = {}
    for e in in_window:
        if e.feature:
            by_feature.setdefault(e.feature, []).append(e)

    velocity: list[FeatureVelocity] = []
    cycle_seconds: list[int] = []
    for fid, fevents in sorted(by_feature.items()):
        intakes = [x.ts for x in fevents if x.command == "/arh-intake"]
        reviews = [
            x.ts
            for x in fevents
            if x.command == "/arh-review" and x.outcome == "completed"
        ]
        first_intake = min(intakes) if intakes else None
        last_review = max(reviews) if reviews else None
        velocity.append(
            FeatureVelocity(
                feature=fid,
                first_intake_ts=first_intake,
                last_review_pass_ts=last_review,
            )
        )
        if first_intake and last_review:
            cycle_seconds.append(int((last_review - first_intake).total_seconds()))

    mean_cycle = int(sum(cycle_seconds) / len(cycle_seconds)) if cycle_seconds else None

    # --- validation rounds (read from state file's validation_summary text)
    rounds: list[float] = []
    for rec in state_raw.values():
        summary = rec.get("validation_summary") if isinstance(rec, dict) else None
        if isinstance(summary, str):
            m = re.search(r"in\s+(\d+)\s+round", summary)
            if m:
                rounds.append(float(m.group(1)))
    validation_rounds_mean = (sum(rounds) / len(rounds)) if rounds else None

    # --- stack-smoke pass rate (parse the Stack smoke row from latest VALIDATION-*.md per feature)
    smoke_pass = 0
    smoke_total = 0
    for body in validation_summaries.values():
        # Look for "| Stack smoke | <total> | <pass> | <fail> | <error> | <flaky> |"
        m = re.search(
            r"\|\s*Stack smoke\s*\|\s*(\d+)\s*\|\s*(\d+)\s*\|\s*(\d+)\s*\|\s*(\d+)\s*\|",
            body,
        )
        if m:
            total = int(m.group(1))
            passed = int(m.group(2))
            if total > 0:
                smoke_total += total
                smoke_pass += passed
    stack_smoke_pass_rate = (smoke_pass / smoke_total) if smoke_total else None

    # --- carry-forward open
    carry_forward_open = 0
    for rec in state_raw.values():
        if isinstance(rec, dict):
            pending = rec.get("pending_carry_forward")
            if isinstance(pending, list):
                # Only count unresolved entries (resolved_at is null)
                carry_forward_open += sum(
                    1 for item in pending if isinstance(item, dict) and not item.get("resolved_at")
                )

    # --- error rate
    errors = sum(1 for e in in_window if e.outcome == "error")
    error_rate = (errors / total_commands) if total_commands else 0.0

    # --- friction per command
    friction = _compute_friction(in_window)

    # --- per-user
    per_user = _compute_per_user(in_window)

    # Code-change activity totals (sum across all in-window entries)
    files_created_total = sum(e.files_created for e in in_window)
    files_modified_total = sum(e.files_modified for e in in_window)
    lines_added_total = sum(e.lines_added for e in in_window)
    tool_rejections_total = sum(e.tool_rejections for e in in_window)

    return KPIWindow(
        window_label=f"last {window_days} days",
        window_start=window_start,
        window_end=window_end,
        active_users=users,
        total_commands=total_commands,
        total_seconds=total_seconds,
        mean_cycle_seconds=mean_cycle,
        velocity=velocity,
        validation_rounds_mean=validation_rounds_mean,
        stack_smoke_pass_rate=stack_smoke_pass_rate,
        carry_forward_open=carry_forward_open,
        error_rate=error_rate,
        friction=friction,
        per_user=per_user,
        files_created_total=files_created_total,
        files_modified_total=files_modified_total,
        lines_added_total=lines_added_total,
        tool_rejections_total=tool_rejections_total,
    )


def group_activity_by_user(
    entries: list[ActivityEntry], *, since: datetime
) -> list[UserSummary]:
    """Return per-user summaries for entries since `since`, sorted by activity desc.

    Each UserSummary also exposes its underlying entries via the side-channel
    `entries_by_user` dict (returned separately by `group_entries_by_user_with_rows`).
    """
    in_window = [e for e in entries if e.ts >= since]
    return _compute_per_user(in_window)


def group_entries_by_user(
    entries: list[ActivityEntry], *, since: datetime
) -> dict[str, list[ActivityEntry]]:
    """Return entries grouped by user, each list sorted by timestamp ascending."""
    in_window = [e for e in entries if e.ts >= since]
    by_user: dict[str, list[ActivityEntry]] = {}
    for e in in_window:
        by_user.setdefault(e.user, []).append(e)
    for v in by_user.values():
        v.sort(key=lambda x: x.ts)
    return by_user


# ---- project totals (till date) -------------------------------------------

# USD per million tokens: model-id prefix -> (input, output). Cache read bills
# 0.1x input; cache writes bill 1.25x (5-minute TTL) or 2x (1-hour TTL) input.
# Source: platform.claude.com pricing (cached 2026-06).
_PRICING: dict[str, tuple[float, float]] = {
    "claude-fable-5": (10.0, 50.0),
    "claude-opus-4-8": (5.0, 25.0),
    "claude-opus-4-7": (5.0, 25.0),
    "claude-opus-4-6": (5.0, 25.0),
    "claude-opus-4-5": (5.0, 25.0),
    "claude-sonnet-4-6": (3.0, 15.0),
    "claude-sonnet-4-5": (3.0, 15.0),
    "claude-haiku-4-5": (1.0, 5.0),
}
_CACHE_READ_MULT = 0.1
_CACHE_WRITE_5M_MULT = 1.25
_CACHE_WRITE_1H_MULT = 2.0
_MTOK = 1_000_000


def _price_for(model: str) -> tuple[float, float] | None:
    for prefix, p in _PRICING.items():
        if model.startswith(prefix):
            return p
    return None


def pricing_reference() -> list[dict[str, float | str]]:
    """Rows for the KPI page's pricing-reference table — derived from the same
    `_PRICING` constants `cost_of_entry` uses, so the page always documents the
    exact rates the costs were computed with."""
    return [
        {
            "model": prefix,
            "input": in_price,
            "output": out_price,
            "cache_read": in_price * _CACHE_READ_MULT,
            "cache_write_5m": in_price * _CACHE_WRITE_5M_MULT,
            "cache_write_1h": in_price * _CACHE_WRITE_1H_MULT,
        }
        for prefix, (in_price, out_price) in _PRICING.items()
    ]


def cost_of_entry(e: ActivityEntry) -> tuple[float, int]:
    """Return (cost_usd, unpriced_tokens) for one activity record.

    Cost is computed from the per-model `models` map. Tokens whose model is
    unknown/unpriced — or all tokens of a legacy record with no `models` map —
    count as unpriced rather than being silently priced at a guessed rate.
    """
    if not e.models:
        return 0.0, e.total_tokens
    cost = 0.0
    unpriced = 0
    for model, agg in e.models.items():
        if not isinstance(agg, dict):
            continue
        inp = int(agg.get("input") or 0)
        out = int(agg.get("output") or 0)
        cr = int(agg.get("cache_read") or 0)
        cw5 = int(agg.get("cache_write_5m") or 0)
        cw1 = int(agg.get("cache_write_1h") or 0)
        price = _price_for(str(model))
        if price is None:
            unpriced += inp + out + cr + cw5 + cw1
            continue
        in_price, out_price = price
        cost += (
            inp * in_price
            + out * out_price
            + cr * in_price * _CACHE_READ_MULT
            + cw5 * in_price * _CACHE_WRITE_5M_MULT
            + cw1 * in_price * _CACHE_WRITE_1H_MULT
        ) / _MTOK
    return cost, unpriced


@dataclass
class PersonaTotals:
    user: str
    sessions: int
    commands: int
    total_seconds: int
    tokens: int
    cost_usd: float
    unpriced_tokens: int

    @property
    def total_label(self) -> str:
        return _humanize_seconds(self.total_seconds)


@dataclass
class FeatureCost:
    feature: str  # "—" for activity with no feature id
    tokens: int
    cost_usd: float


@dataclass
class ProjectTotals:
    """All-time (till date) aggregates across every activity record."""

    sessions_total: int
    commands_total: int
    seconds_total: int
    input_total: int
    output_total: int
    cache_read_total: int
    cache_write_total: int
    tokens_total: int
    cost_total_usd: float
    unpriced_tokens_total: int
    per_persona: list[PersonaTotals]
    per_feature_cost: list[FeatureCost]

    @property
    def seconds_label(self) -> str:
        return _humanize_seconds(self.seconds_total)


def compute_project_totals(entries: list[ActivityEntry]) -> ProjectTotals:
    """Compute till-date totals: sessions, time, tokens, and cost — overall,
    per persona (user), and cost per feature."""
    sessions_total = len({e.session_id for e in entries if e.session_id})
    seconds_total = sum(e.duration_s for e in entries)
    input_total = sum(e.input_token for e in entries)
    output_total = sum(e.output_token for e in entries)
    cache_read_total = sum(e.cache_read for e in entries)
    cache_write_total = sum(e.cache_write for e in entries)
    tokens_total = sum(e.total_tokens for e in entries)

    cost_total = 0.0
    unpriced_total = 0
    per_user: dict[str, PersonaTotals] = {}
    user_sessions: dict[str, set[str]] = {}
    per_feature: dict[str, FeatureCost] = {}
    for e in entries:
        cost, unpriced = cost_of_entry(e)
        cost_total += cost
        unpriced_total += unpriced

        pt = per_user.setdefault(
            e.user,
            PersonaTotals(
                user=e.user, sessions=0, commands=0, total_seconds=0,
                tokens=0, cost_usd=0.0, unpriced_tokens=0,
            ),
        )
        pt.commands += 1
        pt.total_seconds += e.duration_s
        pt.tokens += e.total_tokens
        pt.cost_usd += cost
        pt.unpriced_tokens += unpriced
        if e.session_id:
            user_sessions.setdefault(e.user, set()).add(e.session_id)

        fkey = e.feature or "—"
        fc = per_feature.setdefault(fkey, FeatureCost(feature=fkey, tokens=0, cost_usd=0.0))
        fc.tokens += e.total_tokens
        fc.cost_usd += cost

    for user, pt in per_user.items():
        pt.sessions = len(user_sessions.get(user, set())) or (1 if pt.commands else 0)

    personas = sorted(per_user.values(), key=lambda p: p.tokens, reverse=True)
    feature_costs = sorted(per_feature.values(), key=lambda f: f.cost_usd, reverse=True)
    return ProjectTotals(
        sessions_total=sessions_total,
        commands_total=len(entries),
        seconds_total=seconds_total,
        input_total=input_total,
        output_total=output_total,
        cache_read_total=cache_read_total,
        cache_write_total=cache_write_total,
        tokens_total=tokens_total,
        cost_total_usd=cost_total,
        unpriced_tokens_total=unpriced_total,
        per_persona=personas,
        per_feature_cost=feature_costs,
    )


# ---- internals ------------------------------------------------------------


def _compute_per_user(entries: list[ActivityEntry]) -> list[UserSummary]:
    by_user: dict[str, list[ActivityEntry]] = {}
    for e in entries:
        by_user.setdefault(e.user, []).append(e)
    out: list[UserSummary] = []
    for user, evs in by_user.items():
        sessions = len({e.session_id for e in evs if e.session_id})
        cmd_counts: dict[str, int] = {}
        for e in evs:
            if e.command:
                cmd_counts[e.command] = cmd_counts.get(e.command, 0) + 1
        top_command = max(cmd_counts.items(), key=lambda kv: kv[1])[0] if cmd_counts else "—"
        out.append(
            UserSummary(
                user=user,
                sessions=sessions or 1,
                commands=len(evs),
                total_seconds=sum(e.duration_s for e in evs),
                top_command=top_command,
            )
        )
    out.sort(key=lambda u: u.commands, reverse=True)
    return out


def _compute_friction(entries: list[ActivityEntry]) -> list[CommandFriction]:
    by_cmd: dict[str, list[ActivityEntry]] = {}
    for e in entries:
        if e.command:
            by_cmd.setdefault(e.command, []).append(e)
    out: list[CommandFriction] = []
    for cmd, evs in by_cmd.items():
        runs = len(evs)
        mean_int = sum(e.intervention_count for e in evs) / runs

        # Repeat rate: fraction of features that ran this command 2+ times
        by_feature: dict[str, int] = {}
        for e in evs:
            if e.feature:
                by_feature[e.feature] = by_feature.get(e.feature, 0) + 1
        features_with_repeat = sum(1 for n in by_feature.values() if n >= 2)
        repeat_rate = features_with_repeat / len(by_feature) if by_feature else 0.0

        score = mean_int + repeat_rate * 2.0
        if score >= 3.0:
            tier = "🔴"
        elif score >= 1.5:
            tier = "🟡"
        else:
            tier = "🟢"
        out.append(
            CommandFriction(
                command=cmd,
                runs=runs,
                mean_interventions=mean_int,
                repeat_rate=repeat_rate,
                score=score,
                tier=tier,
            )
        )
    out.sort(key=lambda f: f.score, reverse=True)
    return out


def _humanize_seconds(seconds: int) -> str:
    if seconds <= 0:
        return "—"
    if seconds < 60:
        return f"{seconds}s"
    if seconds < 3600:
        m = seconds // 60
        return f"{m}m"
    if seconds < 86400:
        h, rem = divmod(seconds, 3600)
        m = rem // 60
        return f"{h}h {m:02d}m" if m else f"{h}h"
    d, rem = divmod(seconds, 86400)
    h = rem // 3600
    return f"{d}d {h}h" if h else f"{d}d"


def _humanize_timedelta(delta: timedelta) -> str:
    return _humanize_seconds(int(delta.total_seconds()))


def render_outcome_icon(outcome: str) -> str:
    """Map outcome literal → icon for activity table cells."""
    return {"completed": "✓", "error": "⚠", "aborted": "⊘"}.get(outcome, "?")


def render_intervention_marker(count: int) -> str:
    """Bold + emoji marker when intervention count high; plain otherwise."""
    if count >= 4:
        return f"**{count}** 🔴"
    if count >= 3:
        return f"**{count}** 🟡"
    return str(count)
